cd [REDACTED-HOME]/.claude/projects/-home-[REDACTED-USER]-[REDACTED-GCP-PROJECT]/ && python3 -I - <<'E'
import json,re
for f in ['38dd8981-353b-45be-9a43-7bc7dc3140b6.jsonl','e73dfe31-c4f5-4462-88b4-bec9dcc42812.jsonl']:
    print('#####',f)
    for n,l in enumerate(open(f)):
        try:d=json.loads(l)
        except: continue
        m=d.get('message') or {}
        if m.get('role')!='user' or d.get('isMeta'): continue
        c=m.get('content')
        ts=[c] if isinstance(c,str) else [x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text']
        for t in ts:
            if t.strip() and not t.lstrip().startswith('<system-reminder') and not t.lstrip().startswith('<local-command') and not t.lstrip().startswith('<command'):
                print(f'--- {n} {d.get("timestamp")}\n{t[:3500]}')
    if f.startswith('38dd'):
        L=open(f).readlines()
        for n in range(len(L)-1,max(len(L)-40,0),-1):
            d=json.loads(L[n]); m=d.get('message') or {}
            if m.get('role')=='assistant' and isinstance(m.get('content'),list):
                x=[b['text'] for b in m['content'] if b.get('type')=='text']
                if x: print('=== last assistant',n,d.get('timestamp'),'\n',x[-1][:3000]); break
E

